update public.lessons l set enhancements = $ench${"industryStory":"A manual tester I mentored spent weeks only clicking through the UI. The day she opened the API behind the \"Save\" button, she found the app was silently storing the wrong customer id — a bug no amount of UI testing had surfaced. Understanding what an API is changed how she tested everything after that.","visualAid":{"type":"comparison","title":"The restaurant analogy","headers":["Restaurant","Software"],"rows":[["You (the diner)","The client (app / browser)"],["The waiter","The API"],["The kitchen","The server"],["Your order","The request"],["The food","The response"]]},"davidTip":"Never assume the UI tells the whole truth. The moment you can read the API behind a screen, you can see what the application is *really* doing — and that is where the interesting bugs live.","miniChallenge":"Pick one app you used today. Write one sentence describing something it almost certainly requested from an API, and what it got back.","modelAnswer":"## Example\nA food-delivery app: on open it sent `GET /restaurants?lat=..&lng=..` and got back a JSON list of nearby restaurants (name, rating, delivery time), which it drew as cards.","resourcePreview":{"name":"API Fundamentals Cheat Sheet","purpose":"One-page reference for API vocabulary.","whenToUse":"Keep it open through Module 1.","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A release went out where every API test \"passed\" — because they only checked for `200 OK`. In production the endpoint was returning 200 with an empty body. The lesson stuck: a status code is necessary, never sufficient.","visualAid":{"type":"timeline","title":"The life of a request","steps":[{"label":"Build","detail":"client sets method, URL, headers, body"},{"label":"Send","detail":"request travels to the server"},{"label":"Process","detail":"server runs the logic"},{"label":"Respond","detail":"status + headers + body come back"},{"label":"Read","detail":"tester inspects the response"}]},"davidTip":"Read three things on every response: the status code, the key headers (auth, content-type), and the body. Testers who skip the body ship bugs.","badGood":{"label":"asserting a response","bad":"The test only checks `status == 200`. It passes even when the body is empty or wrong.","good":"The test checks `status == 201`, that the body contains the created `id`, and that returned fields match what was sent."},"miniChallenge":"Write out the four parts of a request that fetches user 7 from `https://api.example.com`.","modelAnswer":"## Example\nMethod: `GET`. URL: `https://api.example.com/users/7`. Headers: `Accept: application/json`. Body: none (GET has no body)."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"An API used `/getUser?id=5` for reads but `/users` for creates — inconsistent and non-RESTful. New joiners kept guessing endpoints wrong. Consistent REST conventions save real time and prevent real mistakes.","visualAid":{"type":"comparison","title":"REST methods on a resource","headers":["Method","Action","Example"],"rows":[["GET","Read","GET /books/12"],["POST","Create","POST /books"],["PUT","Replace","PUT /books/12"],["PATCH","Update part","PATCH /books/12"],["DELETE","Remove","DELETE /books/12"]]},"davidTip":"When an API follows REST properly you can often guess an endpoint correctly first try. When you can't, that unpredictability is a testing risk worth writing down.","miniChallenge":"Design the five REST endpoints (method + path) for managing \"projects\".","modelAnswer":"## Example\n`GET /projects`, `GET /projects/{id}`, `POST /projects`, `PUT /projects/{id}`, `DELETE /projects/{id}`."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team's end-to-end checkout suite was so flaky nobody trusted it. We moved the core checks to the API layer — they ran green in seconds on every commit, and within a week caught a tax-rounding bug that would have shipped.","visualAid":{"type":"timeline","title":"The test pyramid (bottom to top)","steps":[{"label":"Unit","detail":"many · fastest · functions"},{"label":"API / integration","detail":"fewer · fast · services talking"},{"label":"UI / end-to-end","detail":"few · slow · whole app"}]},"davidTip":"If a check can be done at the API layer, it usually should be. Speed, stability, and it runs on every build — three things UI tests struggle to give you.","miniChallenge":"Name two checks that belong at the API layer rather than the UI, and say why for each.","modelAnswer":"## Example\n1) Validating an order total — pure logic, fast and exact at the API. 2) Checking a 404 for a missing resource — trivial at the API, slow via the UI.","portfolioBuilder":"Start an \"API test strategy\" note for your portfolio: which checks you'd place at the API layer vs the UI for a sample feature, and why."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A discount code returned £0.00 off for a valid customer, but the UI just showed full price with no error — so manual UI testing \"passed\" and it reached production. One API assertion on the discounted total would have caught it on day one.","visualAid":{"type":"comparison","title":"API vs UI testing","headers":["Dimension","API","UI"],"rows":[["Speed","Fast","Slow"],["Stability","High","Lower"],["Setup cost","Low","Higher"],["User realism","Lower","High"],["Best for","Logic & data","Real journeys"]]},"davidTip":"When the UI and the API disagree, believe the API — then investigate why the UI hid the truth. A green screen is not proof the data is right.","badGood":{"label":"test strategy","bad":"Every check is done through the UI — slow, flaky, and blind to wrong data behind a \"Success\" message.","good":"Logic, data and edge cases are checked at the API; a small set of true end-to-end journeys is kept at the UI."},"miniChallenge":"Give one bug the UI could report as \"passing\" while the API is actually returning something wrong.","modelAnswer":"## Example\nA profile update shows \"Saved!\" but the API stored the old email because the UI sent a cached value. The UI looks correct; the API response reveals the stale data."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"The testers who get good at APIs fastest all do the same thing: they keep one scratch request open and poke endpoints constantly. Curiosity plus a ready tool beats any amount of reading.","visualAid":{"type":"timeline","title":"Your first request","steps":[{"label":"Install","detail":"download & open Postman"},{"label":"New request","detail":"New → HTTP Request"},{"label":"GET","detail":"jsonplaceholder.typicode.com/users/1"},{"label":"Send","detail":"click Send"},{"label":"Read","detail":"200 OK + JSON body"}]},"davidTip":"Save your first working request into a collection straight away. Your Module 10 portfolio project grows from exactly these small saved requests.","miniChallenge":"Send a GET to `https://jsonplaceholder.typicode.com/posts/1` and note the status code plus two fields from the body.","modelAnswer":"## Example\nStatus `200 OK`. Body fields: `userId` and `title` (also `id`, `body`).","managersReview":{"intro":"If I reviewed your first hands-on setup as a lead, I'd look for:","strengths":["Postman installed and a request sent","You can read the status code and body","First request saved into a collection"],"gaps":["Only reading, never sending","Not noticing the response body","Nothing saved to build on"],"improvements":["Send at least three different GET requests","Change a path/param and observe the change","Name and save your collection clearly"]},"portfolioBuilder":"Create a Postman collection \"API Masterclass — <your name>\" and save your first request into it. This becomes your Module 10 portfolio artefact.","resourcePreview":{"name":"Postman Starter Collection","purpose":"A ready-to-import collection with your first practice requests.","whenToUse":"Import it now and add to it as the course progresses.","formats":["JSON"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 1 and l.lesson_number = 6;

